!async function(){let t=document.getElementById("root");t||(t=document.createElement("div"),t.id="root",document.body.appendChild(t));const e=document.createElement("h1");e.textContent="Flashcards",t.appendChild(e);const n=document.createElement("form");n.id="card-form",n.innerHTML='\n    <label>Front:<br><input id="front" type="text"></label>\n    <label>Back:<br><input id="back" type="text"></label>\n    <label>Hint:<br><input id="hint" type="text"></label>\n    <label>Tags:<br><input id="tags" type="text"></label>\n    <div class="actions">\n      <button type="button" id="clear-btn">Clear All</button>\n      <button type="submit">Save Card</button>\n    </div>\n  ',t.appendChild(n);const a=document.createElement("ul");a.id="list",t.appendChild(a);const{flashcards:l=[]}=await chrome.storage.local.get("flashcards");l.forEach((t=>{const e=document.createElement("li");let n=`<strong>Front:</strong> ${t.front}<br><strong>Back:</strong> ${t.back}`;t.hint&&(n+=`<br><em>Hint: ${t.hint}</em>`),t.tags.length&&(n+=`<br>Tags: ${t.tags.join(", ")}`),e.innerHTML=n,a.appendChild(e)})),document.getElementById("clear-btn").addEventListener("click",(async()=>{await chrome.storage.local.set({flashcards:[]}),a.innerHTML=""})),n.addEventListener("submit",(async t=>{t.preventDefault();const e=document.getElementById("front").value.trim(),l=document.getElementById("back").value.trim(),r=document.getElementById("hint").value.trim(),o=document.getElementById("tags").value.split(",").map((t=>t.trim())).filter(Boolean);if(!e||!l)return;const{flashcards:c=[]}=await chrome.storage.local.get("flashcards"),d={id:`${Date.now()}-${Math.random()}`,front:e,back:l,hint:r,tags:o};c.push(d),await chrome.storage.local.set({flashcards:c});const s=document.createElement("li");let i=`<strong>Front:</strong> ${e}<br><strong>Back:</strong> ${l}`;r&&(i+=`<br><em>Hint: ${r}</em>`),o.length&&(i+=`<br>Tags: ${o.join(", ")}`),s.innerHTML=i,a.appendChild(s),n.reset()}))}();
